# -*- coding: utf-8 -*-
"""
BlokQR - Module 1 (n4) : palier RAPIDE par defaut + flag deep pour le sandbox.

Corrige le bug "failed" intermittent : le sandbox Chromium ne tourne plus dans
le chemin synchrone par defaut. /v1/analyze renvoie un verdict rapide et fiable
(lexical + redirections + domaine + threat intel) -> plus de verdict UNKNOWN du
au depassement de budget. Le rendu Chromium passe derriere un flag deep=True,
reutilise par le futur /v1/analyze/deep (Pro). La cle de cache distingue les
paliers fast/deep.

Modifie :
  * app/pipeline.py        (signature analyze + flag deep + cle de cache)
  * app/analysis_cache.py  (cache_key inclut le palier)

A executer DEPUIS /opt/blokqr/backend :
    cd /opt/blokqr/backend
    python3 patch_m1_fast_tier.py

Idempotent. Contenus base64. Abandon si une ancre est absente. Controle de syntaxe.
"""
import ast, base64, io, sys
dec=lambda s: base64.b64decode(s).decode("utf-8")

PIPE=[['YXN5bmMgZGVmIGFuYWx5emUoCiAgICByZXF1ZXN0OiBBbmFseXplUmVxdWVzdCwgc2V0dGluZ3M6IFNldHRpbmdzLCBzaWduZXI6IFZlcmRpY3RTaWduZXIKKSAtPiBTaWduZWRWZXJkaWN0OgogICAgIiIiRXjDqWN1dGUgbGUgcGlwZWxpbmUgY29tcGxldCBldCByZW52b2llIHVuIHZlcmRpY3Qgc2lnbsOpLiIiIg==', '', '*, deep: bool = False,'], ['ICAgIGNhY2hlID0gZ2V0X2NhY2hlKHNldHRpbmdzKQogICAgY2tleSA9IGNhY2hlX2tleShyZXF1ZXN0KQ==', 'ICAgIGNhY2hlID0gZ2V0X2NhY2hlKHNldHRpbmdzKQogICAgY2tleSA9IGNhY2hlX2tleShyZXF1ZXN0LCBkZWVwKQ==', 'cache_key(request, deep)'], ['', '', '# Palier RAPIDE (gratuit) : pas de rendu Chromium synchrone.']]
CACHE=[['', '', 'deep: bool = False) -> str']]

def apply_edits(path, edits):
    try:
        src=io.open(path,"r",encoding="utf-8").read()
    except FileNotFoundError:
        print("  [IGNORE] %s introuvable"%path); return True
    changed=False
    for old_b,new_b,marker in edits:
        if marker in src: continue
        old=dec(old_b)
        if old not in src:
            print("  [ABORT] %s : ancre absente (%s) -> NON ecrit"%(path,marker)); return False
        src=src.replace(old,dec(new_b),1); changed=True
    if not changed:
        print("  [OK   ] %s : deja applique (idempotent)"%path); return True
    try: ast.parse(src)
    except SyntaxError as e:
        print("  [ABORT] %s : syntaxe invalide -> NON ecrit (%s)"%(path,e)); return False
    io.open(path,"w",encoding="utf-8").write(src)
    print("  [PATCH] %s : modifie"%path); return True

def main():
    ok=True
    ok&=apply_edits("app/pipeline.py", PIPE)
    ok&=apply_edits("app/analysis_cache.py", CACHE)
    if not ok: sys.exit(1)
    print("\n>>> Termine. Reconstruisez l'image puis redemarrez le conteneur.")

if __name__=="__main__":
    main()
